<?php
require_once __DIR__.'/../config/database.php';
require_once __DIR__.'/../includes/functions.php';
require_once __DIR__.'/../includes/admin_crud_helpers.php';
require_role(['admin','guru','siswa']);
$isAdmin = (current_user()['role'] ?? '') === 'admin';
$errors = [];
$edit=null; if($isAdmin && isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM kegiatan WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch(PDO::FETCH_ASSOC);}
if($isAdmin && $_SERVER['REQUEST_METHOD']==='POST'){sg_verify_csrf();$action=$_POST['action']??'';if($action==='delete'){$q=$pdo->prepare('DELETE FROM kegiatan WHERE id=?');$q->execute([(int)$_POST['id']]);sg_flash_redirect('Kegiatan berhasil dihapus.',BASE_URL.'/dashboard/kegiatan.php');}$judul=trim($_POST['judul']??'');$deskripsi=trim($_POST['deskripsi']??'');$tanggal=$_POST['tanggal']??'';$lokasi=trim($_POST['lokasi']??'');if($judul===''||!$tanggal)$errors[]='Judul dan tanggal wajib diisi.';if(!$errors){if($action==='update'){$q=$pdo->prepare('UPDATE kegiatan SET judul=?,deskripsi=?,tanggal=?,lokasi=? WHERE id=?');$q->execute([$judul,$deskripsi,$tanggal,$lokasi,(int)$_POST['id']]);}else{$q=$pdo->prepare('INSERT INTO kegiatan(judul,deskripsi,tanggal,lokasi) VALUES(?,?,?,?)');$q->execute([$judul,$deskripsi,$tanggal,$lokasi]);}sg_flash_redirect('Kegiatan berhasil disimpan.',BASE_URL.'/dashboard/kegiatan.php');}$edit=['id'=>$_POST['id']??0,'judul'=>$judul,'deskripsi'=>$deskripsi,'tanggal'=>$tanggal,'lokasi'=>$lokasi];}
$rows=$pdo->query('SELECT * FROM kegiatan ORDER BY tanggal DESC,id DESC')->fetchAll(PDO::FETCH_ASSOC);$pageTitle='Agenda Kegiatan — STEINS GATE';include __DIR__.'/../includes/dashboard_page_start.php';?>
<div class="page-heading"><div><div class="section-kicker">CLASS ACTIVITIES</div><h1>Agenda <em>Kegiatan.</em></h1><p>Catatan aktivitas dan kebersamaan kelas.</p></div><?php if($isAdmin):?><a href="#form-kegiatan" class="btn btn-brown"><i class="bi bi-plus-lg me-1"></i>Tambah Kegiatan</a><?php endif;?></div><?php sg_show_flash();foreach($errors as $er):?><div class="alert alert-danger"><?=e($er)?></div><?php endforeach;?>
<?php if($isAdmin):?><div class="sg-panel mb-4" id="form-kegiatan"><h3><?=$edit?'Ubah Kegiatan':'Tambah Kegiatan'?></h3><form method="post" class="row g-3"><input type="hidden" name="csrf_token" value="<?=e(sg_csrf_token())?>"><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><?php if($edit):?><input type="hidden" name="id" value="<?=e($edit['id'])?>"><?php endif;?><div class="col-md-6"><label class="form-label">Judul</label><input name="judul" class="form-control custom-input" value="<?=e($edit['judul']??'')?>" required></div><div class="col-md-6"><label class="form-label">Tanggal</label><input type="date" name="tanggal" class="form-control custom-input" value="<?=e($edit['tanggal']??'')?>" required></div><div class="col-md-6"><label class="form-label">Lokasi</label><input name="lokasi" class="form-control custom-input" value="<?=e($edit['lokasi']??'')?>"></div><div class="col-12"><label class="form-label">Deskripsi</label><textarea name="deskripsi" rows="3" class="form-control custom-input"><?=e($edit['deskripsi']??'')?></textarea></div><div class="col-12"><button class="btn btn-brown">Simpan</button> <?php if($edit):?><a class="btn btn-outline-secondary" href="<?=BASE_URL?>/dashboard/kegiatan.php">Batal</a><?php endif;?></div></form></div><?php endif;?>
<div class="row g-3"><?php foreach($rows as $r):?><div class="col-md-6 col-xl-4"><article class="sg-card"><div class="sg-icon"><i class="bi bi-calendar-event"></i></div><div class="sg-meta"><?=date('d M Y',strtotime($r['tanggal']))?></div><h3 class="mt-2"><?=e($r['judul'])?></h3><p><?=nl2br(e($r['deskripsi']??''))?></p><?php if($r['lokasi']):?><div class="sg-meta mt-3"><i class="bi bi-geo-alt"></i> <?=e($r['lokasi'])?></div><?php endif;?><?php if($isAdmin):?><div class="mt-3 d-flex gap-2"><a class="btn btn-sm btn-outline-secondary" href="?edit=<?=$r['id']?>">Edit</a><form method="post" onsubmit="return confirm('Hapus kegiatan ini?')"><input type="hidden" name="csrf_token" value="<?=e(sg_csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-danger">Hapus</button></form></div><?php endif;?></article></div><?php endforeach;?></div><?php if(!$rows):?><div class="sg-panel text-center">Belum ada agenda kegiatan.</div><?php endif;?><?php include __DIR__.'/../includes/dashboard_page_end.php';?>